export const leadTemplate=`<section id="lead" hidden><div class="sectionhead"><div><h2>1분 선출 추천</h2><p>선출 화면 한 장을 OpenAI가 읽습니다. 내·상대 파티를 최종 확인한 뒤 싱글 3마리, 더블 4마리의 순서를 추천합니다.</p></div><span class="tag">빠른 확인 필수</span></div><div class="leadgrid"><div class="uploadpanel"><label class="dropzone"><strong>선출 화면 선택</strong><span>좌측 내 파티 · 우측 상대 파티가 모두 보이는 PNG/JPG/WebP</span><input type="file" id="leadFile" accept="image/png,image/jpeg,image/webp"></label><img id="leadPreview" alt="선출 화면 미리보기" hidden><button id="leadRead" class="primary" disabled>AI로 인식</button><p id="leadStatus" role="status">이미지를 선택하면 OpenAI가 화면을 읽습니다.</p><details><summary>AI 인식 안내</summary><p>한 장의 요청으로 좌측 내 파티와 우측 상대 파티를 각각 읽습니다. 인식 결과는 확정값이 아니며, 잘못된 칸은 검색으로 즉시 교정한 뒤 추천을 실행하세요.</p></details></div><div><div class="leadcolumns"><div><h3>내 파티</h3><div id="leadMine" class="leadslots"></div></div><div><h3>상대 파티</h3><div id="leadOpponent" class="leadslots"></div></div></div><div class="leadactions"><button id="leadRecommend" class="primary" disabled>선출과 순서 추천</button></div><div id="leadResult"></div></div></div></section>`;

export const calculatorTemplate=`<section id="calculators" hidden><div class="sectionhead"><div><h2>챔피언스 계산기</h2><p>공격·방어 포켓몬만 고르면 빠른 결정력 및 스피드 비교를 바로 실행할 수 있습니다. 기술과 배분을 직접 고르는 상세 계산도 지원합니다.</p></div><span class="tag">86~100 난수</span></div><div class="calcgrid"><label>공격 포켓몬<input id="calcAtk" list="calcMons" autocomplete="off"></label><label>방어 포켓몬<input id="calcDef" list="calcMons" autocomplete="off"></label><label>기술<select id="calcMove"></select></label><label>방어 배분<select id="calcBulk"><option value="0,0,0,0,0,0">H0 · B/D0</option><option value="32,0,0,0,0,0">H32 · B/D0</option><option value="32,0,32,0,0,0">H32 · B32</option><option value="32,0,0,0,32,0">H32 · D32</option></select></label></div><div class="calcactions"><button id="calcPowerSweep" class="primary">결정력 일괄 계산</button><button id="calcSpeedCompare" class="primary">스피드 일괄 비교</button><button id="calcRun">선택 기술·배분 상세 계산</button></div><div id="calcResult" class="calcresult"></div><datalist id="calcMons"></datalist></section><dialog id="imageViewer"><div class="dialoghead"><strong>업로드 이미지</strong><button data-close="imageViewer" aria-label="닫기">×</button></div><img id="imageViewerImg" alt="업로드 이미지 크게 보기"></dialog>`;
